using Microsoft.AspNetCore.Mvc;using NovaStore.Services;
namespace NovaStore.Controllers;public class CartController(StoreService store):Controller {public IActionResult Index()=>View(HttpContext.Session.Details(store));[HttpPost,ValidateAntiForgeryToken]public IActionResult Add(int id,int quantity=1,string? returnUrl=null){var product=store.Find(id);if(product==null)return NotFound();var cart=HttpContext.Session.GetCart();var line=cart.FirstOrDefault(x=>x.ProductId==id);if(line==null)cart.Add(new(){ProductId=id,Quantity=Math.Clamp(quantity,1,product.Stock)});else line.Quantity=Math.Clamp(line.Quantity+quantity,1,product.Stock);HttpContext.Session.SetCart(cart);TempData["Toast"]="Added to your bag!";return !string.IsNullOrEmpty(returnUrl)&&Url.IsLocalUrl(returnUrl)?LocalRedirect(returnUrl):RedirectToAction("Index");}[HttpPost,ValidateAntiForgeryToken]public IActionResult Update(int id,int quantity){var cart=HttpContext.Session.GetCart();var line=cart.FirstOrDefault(x=>x.ProductId==id);if(line!=null){if(quantity<=0)cart.Remove(line);else line.Quantity=Math.Clamp(quantity,1,store.Find(id)?.Stock??1);}HttpContext.Session.SetCart(cart);return RedirectToAction("Index");}[HttpPost,ValidateAntiForgeryToken]public IActionResult Remove(int id)=>Update(id,0);}
